INSERT OR REPLACE INTO patterns VALUES ('MCL-TEST-ISSUE', 'webapp', 'test-issue', 4, 'test-failure', 'config', 'high', 'make mycelium work on any repo — fix --init crash, strip NumbahWan refs, fix watch.cjs syntax errors, rename .nw-* to .mycelium-*, tested end-to-end o. RULE: Review carefully before committing.', 'make mycelium work on any repo — fix --init crash, strip NumbahWan refs, fix watch.cjs syntax errors, rename .nw-* to .mycelium-*, tested end-to-end on fresh repo', '2026-07-05T09:05:11.532Z');
INSERT OR REPLACE INTO patterns VALUES ('MCL-CSS-LAYOUT-ISSUE', 'webapp', 'css-layout-issue', 3, 'css-layout', 'html', 'medium', 'repair the silent heal loop — eval bridge, blame guard, recency-aware health. RULE: Test layout at 320px, 768px, 1024px after CSS changes.', 'repair the silent heal loop — eval bridge, blame guard, recency-aware health', '2026-07-05T09:05:11.532Z');
INSERT OR REPLACE INTO patterns VALUES ('MCL-MISSING-RESPONSIVE-BREAKPOINT', 'webapp', 'missing-responsive-breakpoint', 3, 'mobile-compat', 'config', 'medium', 'Test every UI change at 320px, 768px, and 1024px. Add @media breakpoints for layouts that break at different screen sizes.', 'Stats grid was overlapping on small screens due to fixed px positions', '2026-07-05T09:05:11.532Z');
INSERT OR REPLACE INTO patterns VALUES ('MCL-MISSING-PRECONDITION-CHECK', 'webapp', 'missing-precondition-check', 3, 'null-reference', 'html', 'medium', 'Validate prerequisites before executing logic. Check that DOM elements exist, APIs are loaded, and data is present before using them.', 'selfHeal gated at 10 commits, but squash workflow compresses 4-5→1,', '2026-07-05T09:05:11.532Z');
